package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaPlDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Schronienie się przed złem moich czynów", "O Allahu, szukam schronienia u Ciebie przed złem tego, co zrobiłem, i przed złem, którego nie zrobiłem.", "Dua Proroka ﷺ, według Aiszy (RA).", "Ochrona przed konsekwencjami zarówno tego, co zostało zrobione, jak i tego, co pozostało niezrobione."),
        "dua_jahdil_bala" to DuaText("Schronienie przed ciężkimi próbami", "O Allahu, szukam schronienia u Ciebie przed ciężką próbą, przed nieszczęściem, przed złym wyrokiem i przed napaścią wrogów.", "Schronienie się przed surowymi próbami i przed rozkoszą wrogów.", "Prorok ﷺ szukał schronienia przed tymi czterema rzeczami."),
        "dua_fitnat_ghina_faqr" to DuaText("Schronienie przed próbami bogactwa i biedy", "O Allah, szukam u Ciebie schronienia przed lenistwem i starością, przed grzechem i długiem, przed próbą i karą w grobie, przed próbą i karą ognia, przed złem próby bogactwa i próbą ubóstwa.", "Schronienie przed próbami grobu, piekła, bogactwa i biedy (część dua).", "Obszerny duet schronienia przed Prorokiem ﷺ."),
        "dua_kufr_faqr" to DuaText("Schronienie przed niewiarą i ubóstwem", "O Allahu, szukam schronienia u Ciebie przed niewiarą i ubóstwem i szukam schronienia u Ciebie przed karą grobową. Nie ma boga oprócz Ciebie.", "Trzy razy rano i wieczorem.", "Abu Bakrah (RA) słyszał, jak Prorok ﷺ to mówił."),
        "dua_sharri_sami" to DuaText("Schronienie się przed złem moich zmysłów", "O Allahu, szukam schronienia u Ciebie przed złem mojego słuchu, złem mojego wzroku, złem mojego języka, złem mojego serca i złem moich pragnień.", "Nauczał Shakala ibn Humayda (RA).", "Dua chroniąca kończyny i siebie przed grzechem."),
        "dua_hadm_gharaq" to DuaText("Schronienie przed nagłą śmiercią i wypadkami", "O Allahu, szukam schronienia u Ciebie przed przygnieceniem (przez budynek), upadkiem z wysokości, utonięciem, spaleniem i starością; od Szaytana, który sprowadził mnie na manowce w chwili śmierci, od śmierci podczas ucieczki z Twojej ścieżki i od śmierci z powodu (jadowitego) użądlenia.", "Schronienie przed wypadkami i przykrą śmiercią.", "Dua schronienia przed Prorokiem ﷺ."),
        "dua_ju_khiyanah" to DuaText("Schronienie przed głodem i zdradą", "O Allah, szukam schronienia u Ciebie przed głodem, bo jest to zły towarzysz, i szukam u Ciebie schronienia przed zdradą, bo jest to zły powiernik.", "Schronienie przed głodem i zdradą.", "Dua schronienia przed Prorokiem ﷺ."),
        "dua_huda_tuqa" to DuaText("Wskazówki, pobożność, czystość i wystarczalność", "O Allahu, proszę Cię o przewodnictwo, pobożność, czystość i samowystarczalność.", "Krótki, obszerny duet Proroka ﷺ.", "Cztery podstawowe błogosławieństwa religii i tego świata."),
        "dua_aslih_li_dini" to DuaText("Napraw moją religię, świat i życie przyszłe", "O Allahu, popraw moją religię, która jest zabezpieczeniem wszystkich moich spraw; wyprostuj moje światowe życie, w którym jest moje utrzymanie; i napraw moje życie przyszłe, do którego powrócę. Spraw, aby życie było dla mnie pomnożeniem wszelkiego dobra, a śmierć uwolnieniem od wszelkiego zła.", "Reformowanie religii, tego świata i życia ostatecznego – wszystkich trzech.", "Obszerny duet Proroka ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Zwróć nasze serca ku Twojemu posłuszeństwu", "O Allah, Przemieniaczu serc, zwróć nasze serca ku Twojemu posłuszeństwu.", "Dua utrzymująca serce w posłuszeństwie.", "Serca wszystkich ludzi są między dwoma palcami Miłosiernego."),
        "dua_jannah_nar" to DuaText("Prośba o Jannah, schronienie przed ogniem", "O Allahu, proszę Cię o Raj i szukam u Ciebie schronienia przed Ogniem.", "Po tashahhud lub w dowolnym momencie.", "Prorok ﷺ powiedział: nasze dua także krążą wokół tego."),
        "dua_khayri_kullih" to DuaText("Wszystko dobrze, teraz i później", "O Allahu, proszę Cię o wszelkie dobro – natychmiastowe i opóźnione, to, co wiem i czego nie wiem – i szukam u Ciebie schronienia przed wszelkim złem – bezpośrednim i opóźnionym, tym, co wiem i czego nie wiem. O Allah, proszę Cię o Raj i o wszelkie słowa i czyny, które mnie do niego przybliżają, i szukam u Ciebie schronienia przed Ogniem oraz przed wszelkimi słowami i czynami, które mnie do niego przybliżają.", "Prorok ﷺ nauczał tego wszechstronnego duetu Aiszę (RA) (część dua).", "Dua, która gromadzi wszelkie dobro."),
        "dua_ihdini_saddidni" to DuaText("Prowadź mnie i utrzymuj w pionie", "O Allahu, prowadź mnie i utrzymuj na właściwym kursie.", "Prorok ﷺ nauczył tego Alego (RA).", "Pomyśl o przewodnictwie jako o prowadzeniu drogą, a o sadadzie jako o prostocie strzały."),
        "dua_hubbaka" to DuaText("Prośba o miłość Allaha", "O Allahu, proszę Cię o Twoją miłość, miłość tych, którzy Cię kochają, i czyny, które prowadzą mnie do Twojej miłości. O Allahu, spraw, aby Twoja miłość była mi droższa niż ja sam, moja rodzina i zimna woda.", "Dua Dawuda (AS) opowiedziana przez Proroka ﷺ.", "Miłość do Allaha jest największym bogactwem."),
        "dua_filal_khayrat" to DuaText("Czynienie dobra i pozostawienie zła", "O Allahu, proszę Cię, abyś pozwolił mi czynić dobre uczynki, porzucić złe uczynki i kochać biednych, a także abyś mi przebaczył i zlitował się nade mną. A gdy planujesz próbę dla ludu, zabierz mnie bez sądu. Proszę Cię o Twoją miłość, miłość tych, którzy Cię kochają, i miłość do czynów, które przybliżają mnie do Twojej miłości.", "Allah nauczył tego duetu Proroka ﷺ we śnie.", "Prorok ﷺ powiedział: to prawda, więc uczcie się tego i nauczajcie tego."),
        "dua_bi_ilmikal_ghayb" to DuaText("Pozwól mi żyć, póki życie jest dobre", "O Allahu, przez Twoją wiedzę o tym, co niewidzialne i Twoją władzę nad stworzeniem, zachowaj mnie przy życiu, dopóki wiesz, że życie jest dla mnie lepsze, i zabierz mnie, gdy wiesz, że śmierć jest dla mnie lepsza. O Allahu, proszę Cię o strach przed Tobą w życiu prywatnym i publicznym, o słowo prawdy w zadowoleniu i gniewie oraz o umiar w biedzie i bogactwie.", "Duet modlitewny Ammara ibn Yasira (RA) (część otwierająca).", "Prorok ﷺ uczynił to dua w modlitwie."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "O Allahu, proszę Cię, bo Tobie należy się wszelka chwała; nie ma boga oprócz Ciebie, Dawcy łask, Twórcy niebios i ziemi. O Posiadaczu Majestatu i Honoru, O Wiecznie Żyjący, O Podtrzymujący!", "Prorok ﷺ powiedział, że ten człowiek stworzył dua z Największym Imieniem Allaha.", "Dua stworzona z tym Imieniem zostaje udzielona."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "O Allah, proszę Cię, bo świadczę, że Ty jesteś Allahem. nie ma boga oprócz Ciebie, Jedynego, Samowystarczalnego, który nie rodzi, ani się nie rodzi, i nie ma nikogo, kto mógłby się z Nim równać.", "Prorok ﷺ powiedział, że ten człowiek zapytał Allaha poprzez Jego Największe Imię.", "Zapytany przez nią, daje; gdy go wezwie, odpowiada."),
        "dua_thabbitni_hadiyan" to DuaText("Uczyń mnie mocnym, prowadzonym i przewodnikiem", "O Allahu, umocnij mnie i uczyń mnie tym, który prowadzi i jest prowadzony.", "Prorok ﷺ stworzył ten dua dla Jarira (RA) (dla siebie powiedz „thabbitni”).", "Oryginalny dua dla Jarira (RA) używa słów „thabbit-hu”."),
        "dua_rabbighfir_tub_alayya" to DuaText("Wybacz mi i przyjmij moją skruchę", "Panie mój, przebacz mi i przyjmij moją skruchę. Zaprawdę, Ty jesteś Przyjmujący pokutę, Miłosierny.", "Sto razy podczas jednego posiedzenia – praktyka Proroka ﷺ.", "Towarzysze policzyli, że Prorok ﷺ powiedział to sto razy podczas jednego posiedzenia."),
        "dua_rafiq_ala" to DuaText("Dua umierającego", "O Allahu, przebacz mi, zlituj się nade mną i dołącz do mnie z Najwyższym Towarzyszem.", "Ostatni dua Proroka ﷺ — niech chory powie sam za siebie.", "Prorok ﷺ uczynił to dua w chwili swojej śmierci."),
        "dua_la_bas_tahur" to DuaText("Pocieszanie chorych: oczyszczenie", "Bez szkody; jest to oczyszczenie (z grzechów), jeśli Allah zechce.", "Aby pocieszyć chorych podczas odwiedzin.", "Prorok ﷺ powiedział to podczas odwiedzania chorych."),
        "dua_talqeen" to DuaText("Talqeen dla umierających", "Nikt nie jest godny czci poza Allahem.", "Recytuj kalimę w pobliżu umierającej osoby (nie zmuszaj jej do tego).", "Ktokolwiek ostatnie słowa zabrzmi „La ilaha illallah”, wejdzie do Raju (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Zamiast pragnąć śmierci", "O Allahu, zachowaj mnie przy życiu tak długo, jak życie będzie dla mnie lepsze, i zabierz mnie, gdy śmierć będzie dla mnie lepsza.", "Zamiast pragnąć śmierci w trudach.", "Prorok ﷺ zabraniał pragnienia śmierci i zamiast tego nauczał tego."),
        "dua_for_one_i_cursed" to DuaText("Dla kogoś, kogo zraniłem słowami", "O Allahu, każdego wierzącego, którego obraziłem, uczyń to dla niego środkiem bliskości z Tobą w Dniu Zmartwychwstania.", "Dla kogoś, komu źle powiedziałaś w złości.", "Dua Proroka ﷺ."),
        "dua_praising_someone" to DuaText("Kiedy kogoś chwalisz", "Uważam, że taki a taki jest taki i Allah jest jego Rachmistrzem i nie ręczę za niczyją czystość przed Allahem.", "Kiedy kogoś chwalisz, zamiast przesadzać.", "Prorok ﷺ nauczał tej etykiety pochwały."),
        "dua_being_praised" to DuaText("Kiedy jesteś chwalony", "O Allahu, nie bierz mnie za to, co mówią, i przebacz mi to, czego nie wiedzą.", "Słuchanie pochwał — praktyka Towarzysza (RA).", "Sposób na uniknięcie arogancji podczas pochwał."),
        "dua_non_muslim_sneezes" to DuaText("Kiedy niemuzułmanin kicha", "Niech Allah cię prowadzi i uporządkuje twoje sprawy.", "Kiedy niemuzułmanin kicha i mówi „Alhamdulillah”.", "Żydzi kichali w pobliżu Proroka ﷺ, mając nadzieję, że powie „Jarhamukallah” i powiedział to."),
        "dua_reply_ahl_kitab_salam" to DuaText("Odpowiadając Salamowi Ludzi Księgi", "I na ciebie.", "Kiedy Lud Księgi pozdrawia salam.", "Instrukcja Proroka ﷺ."),
        "dua_fasting_invited" to DuaText("Kiedy zaproszono podczas postu", "Poszczę.", "Gdy zostaniesz zaproszony podczas postu lub gdy ktoś się z tobą pokłóci.", "Jeśli poszczący przyjmie zaproszenie, powinien pomodlić się za gospodarza."),
        "dua_for_who_gave_drink" to DuaText("Dla tego, kto mnie nakarmił", "Allahu, nakarm tego, który mnie nakarmił i daj pić temu, który dał mi pić.", "Za tego, kto daje wam jedzenie i napoje.", "Prorok ﷺ stworzył ten dua dla al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Powitanie Eid", "Niech Allah przyjmie (dobre uczynki) od nas i od was.", "Do siebie nawzajem w dniu Eid – praktyka szlachetnych Towarzyszy (RA).", "Towarzysze powiedzieli to, kiedy spotkali się w święto Eid."),
        "dua_wedding_night" to DuaText("Dla panny młodej po Nikah", "O Allahu, proszę Cię o jej dobro i dobro natury, z jaką ją stworzyłeś, i szukam u Ciebie schronienia przed jej złem i złem natury, z jaką ją stworzyłeś.", "Po nikah położenie dłoni na czole żony.", "Nauczanie Proroka ﷺ — błogosławieństwo w małżeństwie."),
        "dua_istisqa_ibadak" to DuaText("Napoj swoje sługi i zwierzęta", "O Allahu, daj wodę swoim sługom i zwierzętom, rozpowszechnij swoje miłosierdzie i przywróć życie swojej martwej krainie.", "Prośba o deszcz (istisqa).", "Prorok ﷺ stworzył tę dua na deszcz."),
        "dua_seeing_clouds" to DuaText("Widząc ciemne chmury", "O Allahu, szukam schronienia u Ciebie przed jego złem.", "Widząc ciemne chmury na niebie; jeśli pada deszcz, powiedz „Allahumma sayyiban nafi'a”.", "Widząc chmury, Prorok ﷺ porzucał to, co robił i tworzył dua."),
        "dua_jamarat" to DuaText("Ukamienowanie Jamaratu", "Allah jest Największy.", "Z każdym rzuconym kamykiem.", "Prorok ﷺ powiedział takbir z każdym kamykiem, następnie po pierwszym i drugim dżamrze zmierzył się z Qiblah i wykonał długi dua."),
        "dua_rabbi_ainni" to DuaText("Panie mój, pomóż mi, a nie przeciwko mnie", "Panie mój, pomóż mi i nie pomagaj innym przeciwko mnie, daj mi zwycięstwo i nie daj innym zwycięstwa nade mną, planuj dla mnie i nie planuj przeciwko mnie, prowadź mnie i ułatwiaj mi prowadzenie oraz pomóż mi przeciwko temu, kto mnie skrzywdzi.", "Obszerny duet Proroka ﷺ (część otwierająca).", "Dua, która gromadzi wszelką pomoc w religii i na tym świecie."),
        "dua_ati_nafsi_taqwaha" to DuaText("Daj mojej duszy Taqwa", "O Allahu, obdarz moją duszę pobożnością i oczyść ją, bo Ty jesteś najlepszy w jej oczyszczeniu. Jesteś jego Strażnikiem i Panem.", "Dla zreformowania i oczyszczenia siebie.", "Prorok ﷺ zwykł tworzyć ten duet."),
        "dua_iqsim_lana_khashyatik" to DuaText("Daj nam taki strach przed Tobą", "O Allahu, daj nam dość strachu przed Tobą, abyśmy stanęli między nami a nieposłuszeństwem wobec Ciebie, dość posłuszeństwa, abyśmy zaprowadzili nas do Twojego Raju i wystarczającą pewność, aby nieszczęścia tego świata były dla nas łatwe. Cieszmy się naszym słuchem, wzrokiem i siłą, dopóki utrzymujesz nas przy życiu i sprawiasz, że przetrwają. Zemścijcie się na tych, którzy nas krzywdzą, pomóżcie nam w walce z naszymi wrogami, nie pozwólcie, aby nasze nieszczęście było w naszej religii, nie czyńcie tego świata naszym największym zmartwieniem lub granicą naszej wiedzy i nie stawiajcie nad nami tych, którzy nie okażą nam miłosierdzia.", "Wstając ze zgromadzenia – Prorok ﷺ rzadko wstawał bez zrobienia tego duetu.", "Kompleksowy duet dla dobra religii, tego świata i zaświatów."),
        "dua_infani_bima_allamtani" to DuaText("Przynieś mi korzyść tym, czego mnie nauczyłeś", "O Allahu, obdarz mnie tym, czego mnie nauczyłeś, naucz mnie, co przyniesie mi korzyść i pomnóż moją wiedzę.", "W trakcie poszukiwania wiedzy lub przed nauką.", "Duet korzystnej wiedzy i działania na jej podstawie."),
    )
}
